import {createPanelMotion} from './panel-motion.js';
import {mountPractice} from './practice.js';
import {createStore,createId} from './store.js';
import {disciplineConfigs,buildQuest,deriveProgress,artifactEvidence} from './quests.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let toastTimer,activePanel='',activeDiscipline='writer',handoffDiscipline=null,destroyed=false,frame=0;
const cleanups=[],mounted=new Map(),mounting=new Map(),pendingInputs=new Map();
const panelMotion=createPanelMotion($('selfmade'));cleanups.push(()=>panelMotion.destroy());
function notify(text){$('play-toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('play-toast').textContent='',5500);}
const store=createStore({onStatus(s){const el=$('storage-status');el.textContent=s.message;el.classList.toggle('problem',!!s.problem);}});
const art={writer:'031',mc:'032',dj:'012',breaking:'033',knowledge:'044'};
const panels=['base','quests','workshop','field','journal'];
const subpanels={'principle-desk':'base','sound-lab':'base','field-stage':'field','field-route-title':'field'};
function save(fn){const ok=store.update(fn);if(!ok)notify('Změna zůstává v paměti. Exportuj ji v Blackbooku; úložiště nepotvrdilo zápis.');return ok;}
function flushInputs(){if(!pendingInputs.size)return;const inputs=[...pendingInputs.values()];pendingInputs.clear();save(s=>{for(const patch of inputs){const q=s.quests.find(q=>q.id===patch.questId);if(q){q.responses||={};q.responses[patch.stepId]=patch.text;}}});}
function setMotion(){const s=store.get().settings;const quiet=reduced.matches||s.motion!=='full';document.documentElement.dataset.motion=quiet?'off':'on';document.documentElement.dataset.selfmadeMotion=s.motion;document.documentElement.dataset.day=s.day;document.documentElement.dataset.atmosphere=s.atmosphere;$('motion-control').textContent=reduced.matches?'POHYB: DLE SYSTÉMU':s.motion==='full'?'POHYB: PLNÝ':s.motion==='reduced'?'POHYB: KLIDNÝ':'POHYB: VYPNUTÝ';$('motion-control').setAttribute('aria-pressed',String(quiet));}
function refreshHud(){const state=store.get(),p=deriveProgress(state);$('hud-alias').textContent=state.profile.alias||'TVŮJ PŘÍBĚH';$('world-alias').textContent=state.profile.alias||'UNTITLED';$('hud-progress').textContent=`${p.attempts} vlastních pokusů / ${p.revisions} vysvětlených revizí`;$('next-step').innerHTML=`<p class="eyebrow">DALŠÍ SMYSLUPLNÝ KROK</p><h4>${p.attempts?'TVŮJ DALŠÍ POSUN.':'ZAČNI NEHOTOVÝM.'}</h4><p>${esc(p.nextStep)}</p><a href="#workshop">Otevřít dílnu ↗</a>`;setMotion();window.dispatchEvent(new CustomEvent('caisik:world',{detail:{alias:state.profile.alias,count:p.artifacts,discipline:activeDiscipline,phase:p.revisions?1:p.attempts?.6:.15,day:state.settings.day}}));}
function fillProfile(){const {profile:p,settings:s}=store.get(),f=$('profile-form');for(const name of ['alias','intent','minutes','mode','future','symbol'])f.elements.namedItem(name).value=p[name];f.elements.namedItem('codex').value=p.codex.join('\n');for(const input of f.querySelectorAll('[name=disciplines]'))input.checked=p.disciplines.includes(input.value);$('world-day').value=s.day;$('world-atmosphere').value=s.atmosphere;}
function ensureQuest(id){let q=store.get().quests.find(q=>q.discipline===id&&q.type==='main');if(!q){q=buildQuest(id);save(s=>{s.quests.push(q);});}return store.get().quests.find(x=>x.id===q.id)||q;}
function renderQuests(){flushInputs();const state=store.get();$('quest-paths').innerHTML=Object.values(disciplineConfigs).map(c=>`<button type="button" data-quest-path="${c.id}" aria-pressed="${c.id===activeDiscipline}">${esc(c.label)}</button>`).join('');const c=disciplineConfigs[activeDiscipline],q=state.quests.find(x=>x.discipline===activeDiscipline&&x.type==='main');const works=state.artifacts.filter(a=>a.discipline===activeDiscipline);const evidence=works.map(a=>({a,e:artifactEvidence(a)}));const ready=evidence.filter(x=>x.e.evidenceReady);$('quest-detail').innerHTML=`<div class="quest-layout"><div class="quest-cover"><img src="/assets/masterworks-v2/${art[c.id]}.webp" alt="Autorská CAISIK ilustrace; nejde o odbornou demonstraci." width="1536" height="1024" loading="lazy"><p class="eyebrow">${esc(c.label)} / TVŮJ VLASTNÍ VÝSTUP</p><h4>${esc(c.title)}</h4><p>${esc(c.output)}</p><a href="${c.href}">Celá expedice, kontext a místa ↗</a><div class="evidence-strip"><strong>${ready.length?'VLASTNÍ REVIZE JE DOLOŽENÁ':'PŘÍBĚH ČEKÁ NA VLASTNÍ DŮKAZ'}</strong><p>${works.length} projektů / ${evidence.filter(x=>x.e.hasRevision).length} skutečně změněných verzí</p><p>Stav popisuje uloženou práci, ne odborné zvládnutí disciplíny.</p>${evidence.map(({a,e})=>`<p><span data-i18n-user>${esc(a.title)}</span> → <span>${esc(e.status)}</span></p>`).join('')}</div><label>Vybavení<select id="quest-equipment"><option value="phone">Telefon</option><option value="paper">Papír a tužka</option><option value="studio">Studio / dílna</option></select></label><p id="equipment-hint">${esc(c.equipment[q?.equipment||'phone'])}</p><label>Tvůrčí omezení<input id="quest-constraint" maxlength="300" value="${esc(q?.constraint||'')}" placeholder="Např. dva odstíny, tři detaily"></label><p>Nápověda po vrstvách:</p>${c.hints.map((h,i)=>`<details><summary>${i+1}. podnět +</summary><p>${esc(h)}</p></details>`).join('')}<a class="play-button primary" href="#workshop">ZAČÍT VLASTNÍ POKUS ↗</a></div><div class="quest-steps">${c.steps.map(step=>`<article class="quest-step"><div><h4>${esc(step.title)}</h4><p>${esc(step.prompt)}</p><label>Moje odpověď / ${esc(step.title)}<textarea rows="3" maxlength="6000" data-quest-response="${step.id}" placeholder="Tvůj konkrétní postřeh…">${esc(q?.responses?.[step.id]||'')}</textarea></label></div></article>`).join('')}</div></div>`;if(q)$('quest-equipment').value=q.equipment||'phone';renderCustom();}
function renderCustom(){const quests=store.get().quests.filter(q=>q.type==='custom'&&q.status!=='archived');$('custom-quests').innerHTML=quests.map(q=>`<article class="custom-item"><p class="eyebrow">VLASTNÍ EXPEDICE / ${esc(q.status==='open'?'ROZPRACOVÁNO':q.status)}</p><h4 data-i18n-user>${esc(q.title)}</h4><p data-i18n-user>${esc(q.goal)}</p><p><strong>Výstup:</strong> <span data-i18n-user>${esc(q.output)}</span></p><p><strong>Vlastní kritérium:</strong> <span data-i18n-user>${esc(q.criteria)}</span></p><label>Přiřadit konkrétní práci<select data-custom-artifact="${esc(q.id)}"><option value="">Zatím bez vlastního díla</option>${store.get().artifacts.map(a=>`<option data-i18n-user value="${esc(a.id)}"${q.artifactId===a.id?' selected':''}>${esc(a.title)}</option>`).join('')}</select></label><button type="button" data-archive-quest="${esc(q.id)}">Archivovat zadání</button></article>`).join('');}
async function openPanel(id,{focus=false}={}){if(!panels.includes(id))id='base';flushInputs();activePanel=id;window.dispatchEvent(new CustomEvent('caisik:panel',{detail:{panel:id}}));const switched=await panelMotion.show(id);if(!switched||destroyed||activePanel!==id)return;document.querySelectorAll('[data-panel]').forEach(a=>{if(a.dataset.panel===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(id==='quests'){ensureQuest(activeDiscipline);renderQuests();}if(id==='workshop'){const target=handoffDiscipline||store.get().drafts.workshops?.active||activeDiscipline;handoffDiscipline=null;save(s=>{s.drafts.workshops||={};s.drafts.workshops.active=target;});window.dispatchEvent(new CustomEvent('caisik:discipline',{detail:{discipline:target}}));}if(!['base','quests'].includes(id)&&!mounted.has(id)){if(!mounting.has(id)){const module=id==='workshop'?'workshops':id;mounting.set(id,import(`./${module}.js?v=3`).then(mod=>{if(destroyed)return;const fn=mod[{workshop:'mountWorkshops',field:'mountField',journal:'mountJournal'}[id]];mounted.set(id,fn($(id),{store,notify}));}).catch(error=>{mounting.delete(id);$(id).innerHTML=`<p>Prostor se nepodařilo načíst. Tvoje data zůstávají zachovaná.</p><button type="button" data-retry="${id}">Zkusit znovu</button>`;console.error('Selfmade module load failed',error);}));}await mounting.get(id);}if(destroyed||activePanel!==id)return;if(focus){$('selfmade').scrollIntoView({behavior:'instant'});}save(s=>{s.drafts.shell={...(s.drafts.shell||{}),panel:id,discipline:activeDiscipline};});}
$('profile-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const durable=save(s=>{s.profile={...s.profile,alias:String(f.get('alias')).trim(),intent:String(f.get('intent')).trim(),disciplines:f.getAll('disciplines'),minutes:Number(f.get('minutes')),mode:String(f.get('mode')),codex:String(f.get('codex')).split('\n').map(x=>x.trim()).filter(Boolean).slice(0,3),future:String(f.get('future')),symbol:String(f.get('symbol'))};if(s.profile.disciplines.length)activeDiscipline=s.profile.disciplines[0];s.events.push({id:createId('event'),type:'profile',createdAt:new Date().toISOString(),text:'Vlastní záměr a cesta.'});});if(durable)notify('Tvůj svět má vlastní jméno. První pokus čeká v dílně.');location.hash='quests';});
$('world-day').addEventListener('change',e=>save(s=>{s.settings.day=e.target.value;}));$('world-atmosphere').addEventListener('change',e=>save(s=>{s.settings.atmosphere=e.target.value;}));$('motion-control').addEventListener('click',()=>save(s=>{s.settings.motion=s.settings.motion==='full'?'reduced':s.settings.motion==='reduced'?'off':'full';}));
$('custom-quest-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const quest=buildQuest('custom',{title:String(f.get('title')),goal:String(f.get('question')),output:String(f.get('output')),criteria:String(f.get('criteria')),type:'custom'});const durable=save(s=>{s.quests.push(quest);});e.currentTarget.reset();renderCustom();if(durable)notify('Vlastní expedice je uložená. Výstup k ní připojíš ze své tvorby.');});
function handleClick(e){const retry=e.target.closest('[data-retry]');if(retry)openPanel(retry.dataset.retry);const path=e.target.closest('[data-quest-path]');if(path){activeDiscipline=path.dataset.questPath;ensureQuest(activeDiscipline);renderQuests();refreshHud();}const archive=e.target.closest('[data-archive-quest]');if(archive){save(s=>{const q=s.quests.find(x=>x.id===archive.dataset.archiveQuest);if(q)q.status='archived';});renderCustom();}const anchor=e.target.closest('a[href^="#"]');if(anchor&&panels.includes(anchor.hash.slice(1))){e.preventDefault();const id=anchor.hash.slice(1);if(id==='workshop'&&anchor.closest('#quest-detail'))handoffDiscipline=activeDiscipline;if(location.hash===anchor.hash)openPanel(id,{focus:true});else location.hash=anchor.hash;}}
function handleInput(e){if(e.target.matches('[data-quest-response]')){const q=store.get().quests.find(q=>q.discipline===activeDiscipline&&q.type==='main');if(q)pendingInputs.set(q.id+e.target.dataset.questResponse,{questId:q.id,stepId:e.target.dataset.questResponse,text:e.target.value});}}
function handleChange(e){if(e.target.matches('[data-quest-response]'))flushInputs();if(e.target.matches('#quest-equipment,#quest-constraint')){const value=e.target.value,key=e.target.id==='quest-equipment'?'equipment':'constraint';save(s=>{const q=s.quests.find(q=>q.discipline===activeDiscipline&&q.type==='main');if(q)q[key]=value;});if(key==='equipment')$('equipment-hint').textContent=disciplineConfigs[activeDiscipline].equipment[value];}if(e.target.matches('[data-custom-artifact]')){save(s=>{const q=s.quests.find(q=>q.id===e.target.dataset.customArtifact);if(q)q.artifactId=e.target.value;});}}
async function onHash(){const id=location.hash.slice(1);if(panels.includes(id))await openPanel(id,{focus:true});else if(subpanels[id]){await openPanel(subpanels[id]);if(activePanel===subpanels[id])$(id)?.scrollIntoView({behavior:'instant',block:'start'});}}
function onScroll(){if(frame||destroyed)return;frame=requestAnimationFrame(()=>{frame=0;const r=$('selfmade').getBoundingClientRect();const p=Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight+Math.min(r.height,innerHeight*2))));document.documentElement.style.setProperty('--journey-progress',p.toFixed(4));});}
function onVisibility(){if(document.hidden)flushInputs();}
document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);document.addEventListener('visibilitychange',onVisibility);window.addEventListener('hashchange',onHash);window.addEventListener('scroll',onScroll,{passive:true});reduced.addEventListener('change',setMotion);
cleanups.push(mountPractice($('principle-desk'),{store,notify}));
let soundMounted=false;async function loadSound(){if(soundMounted||destroyed)return;soundMounted=true;try{const {mountSound}=await import('./sound.js');if(!destroyed)cleanups.push(mountSound($('sound-lab'),{store,notify}));}catch{soundMounted=false;$('sound-lab').innerHTML='<p>Zvuková dílna se nenačetla. Textová tvorba zůstává dostupná.</p>';}}
const soundObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){loadSound();soundObserver.disconnect();}},{rootMargin:'300px'}):null;soundObserver?.observe($('sound-lab'));if(!soundObserver)loadSound();cleanups.push(()=>soundObserver?.disconnect());
cleanups.push(store.subscribe(refreshHud));fillProfile();refreshHud();activeDiscipline=store.get().drafts.shell?.discipline||store.get().profile.disciplines[0]||'writer';if(!disciplineConfigs[activeDiscipline])activeDiscipline='writer';if(subpanels[location.hash.slice(1)])onHash();else openPanel(panels.includes(location.hash.slice(1))?location.hash.slice(1):store.get().drafts.shell?.panel||'base');
customElements.whenDefined('selfmade-world').then(()=>{if(!destroyed)refreshHud();});
function pageHide(e){flushInputs();if(e.persisted)return;destroyed=true;clearTimeout(toastTimer);cancelAnimationFrame(frame);for(const fn of mounted.values())if(typeof fn==='function')fn();for(const fn of cleanups)fn();store.destroy();document.removeEventListener('click',handleClick);document.removeEventListener('input',handleInput);document.removeEventListener('change',handleChange);document.removeEventListener('visibilitychange',onVisibility);window.removeEventListener('hashchange',onHash);window.removeEventListener('scroll',onScroll);reduced.removeEventListener('change',setMotion);}
window.addEventListener('pagehide',pageHide);
